from money import Money

class Cart:
    def __init__(self):
        self.items = []

    def add_item(self, price_cents):
        self.items.append(price_cents)

    def subtotal_cents(self):
        return sum(self.items)

    def total_cents(self, discount_percent=0):
        subtotal = self.subtotal_cents()
        discount_amount = subtotal * (discount_percent / 100)
        total = subtotal - discount_amount
        if total < 0:
            total = 0
        return int(total * 100)

    def receipt(self, discount_percent=0):
        total_cents = self.total_cents(discount_percent)
        total_eur = total_cents / 100
        return f"Total: {total_eur:.2f} EUR"
```

